from __future__ import annotations
from pathlib import Path


def make_project(out: Path):
    (out/'world').mkdir(parents=True, exist_ok=True)
    (out/'scripts').mkdir(parents=True, exist_ok=True)
    project='''[application]\nconfig/name="Vice City Godot - Full Map"\nrun/main_scene="res://world/ViceCity.tscn"\n[display]\nwindow/size/viewport_width=1280\nwindow/size/viewport_height=720\nwindow/size/window_width_override=1280\nwindow/size/window_height_override=720\n[rendering]\nrenderer/rendering_method="gl_compatibility"\nrenderer/rendering_method.mobile="gl_compatibility"\ntextures/default_filters/use_nearest_mipmap_filter=false\n\n[physics]\ncommon/physics_ticks_per_second=60\n'''
    (out/'project.godot').write_text(project, encoding='utf-8')

    streamer='''extends Node3D\n\n@export var chunk_size: float = 512.0\n@export var high_radius: int = 1\n@export var lod_radius: int = 3\n@export var unload_radius: int = 4\n@export var target_path: NodePath = NodePath("Player/Head/Camera3D")\nvar loaded: Dictionary = {}\nvar center := Vector2i(999999,999999)\nvar target: Node3D\nvar collision_triangles := 0\n\nfunc _ready() -> void:\n    target = get_node_or_null(target_path)\n    if target == null:\n        target = get_node_or_null("Player")\n    if target == null:\n        target = self\n    _refresh(true)\n\nfunc _process(_delta: float) -> void:\n    _refresh(false)\n\nfunc _chunk_coord(v: Vector3) -> Vector2i:\n    return Vector2i(floori(v.x / chunk_size), floori(v.z / chunk_size))\n\nfunc _refresh(force: bool) -> void:\n    var c := _chunk_coord(target.global_position)\n    if not force and c == center:\n        return\n    center = c\n\n    # Near chunks use high-detail geometry + collision. Farther chunks use only LOD.\n    for x in range(c.x-lod_radius, c.x+lod_radius+1):\n        for z in range(c.y-lod_radius, c.y+lod_radius+1):\n            var cc := Vector2i(x,z)\n            var near := abs(x-c.x) <= high_radius and abs(z-c.y) <= high_radius\n            _ensure_chunk(cc, near)\n\n    for cc in loaded.keys().duplicate():\n        if abs(cc.x-c.x) > unload_radius or abs(cc.y-c.y) > unload_radius:\n            var n=loaded[cc]\n            if is_instance_valid(n): n.queue_free()\n            loaded.erase(cc)\n\nfunc _ensure_chunk(cc: Vector2i, near: bool) -> void:\n    var wanted := "high" if near else "lod"\n    if loaded.has(cc):\n        var current = loaded[cc]\n        if is_instance_valid(current) and current.get_meta("kind", "") == wanted:\n            return\n        if is_instance_valid(current): current.queue_free()\n        loaded.erase(cc)\n\n    var high_path="res://world/chunks/chunk_%d_%d.tscn" % [cc.x,cc.y]\n    var lod_path="res://world/chunks/chunk_%d_%d_lod.tscn" % [cc.x,cc.y]\n    var high_glb="res://world/chunks/chunk_%d_%d.glb" % [cc.x,cc.y]\n    var lod_glb="res://world/chunks/chunk_%d_%d_lod.glb" % [cc.x,cc.y]\n    var path := high_path if near else lod_path\n    if ResourceLoader.exists(path) == false:\n        path = high_path if near else lod_path\n    if ResourceLoader.exists(path) == false:\n        # The importer can omit tiny/empty LOD chunks; fall back to the high GLB.\n        path = high_glb if near else lod_glb\n    if ResourceLoader.exists(path) == false:\n        return\n    var scene=load(path)\n    if scene == null: return\n    var node=scene.instantiate()\n    node.set_meta("kind", wanted)\n    add_child(node)\n    loaded[cc]=node\n    if near:\n        _attach_collision(node, cc)\n\nfunc _attach_collision(parent: Node3D, cc: Vector2i) -> void:\n    var path="res://world/collision/chunk_%d_%d.bin" % [cc.x,cc.y]\n    if not FileAccess.file_exists(path): return\n    var data=FileAccess.get_file_as_bytes(path)\n    var stream=StreamPeerBuffer.new()\n    stream.data_array=data\n    if stream.get_size() < 8: return\n    var magic=stream.get_data(4)\n    if magic.size()!=4 or magic.get_string_from_ascii()!="VCOL": return\n    var point_count=stream.get_u32()\n    if point_count < 3 or point_count > 5000000: return\n    var faces=PackedVector3Array()\n    faces.resize(point_count)\n    for i in range(point_count):\n        faces[i]=Vector3(stream.get_float(),stream.get_float(),stream.get_float())\n    var shape=ConcavePolygonShape3D.new()\n    shape.set_faces(faces)\n    var body=StaticBody3D.new()\n    body.collision_layer=1\n    body.collision_mask=1\n    body.name="Collision"\n    var cs=CollisionShape3D.new()\n    cs.shape=shape\n    body.add_child(cs)\n    parent.add_child(body)\n    collision_triangles += point_count/3\n\nfunc _unhandled_input(e) -> void:\n    if e is InputEventKey and e.pressed and e.keycode == KEY_F3:\n        print("Loaded chunks: ",loaded.size()," collision triangles: ",collision_triangles)\n'''
    (out/'scripts/WorldStreamer.gd').write_text(streamer, encoding='utf-8')

    player='''extends CharacterBody3D\n\n@export var walk_speed := 7.5\n@export var sprint_speed := 16.0\n@export var jump_velocity := 6.0\n@export var mouse_sensitivity := 0.12\n@onready var camera: Camera3D = $Head/Camera3D\n@onready var head: Node3D = $Head\nvar pitch := -8.0\nvar yaw := 0.0\nvar captured := true\n\nfunc _ready() -> void:\n    Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)\n\nfunc _unhandled_input(e) -> void:\n    if e is InputEventKey and e.pressed and e.keycode == KEY_ESCAPE:\n        captured = not captured\n        Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED if captured else Input.MOUSE_MODE_VISIBLE)\n    elif captured and e is InputEventMouseMotion:\n        yaw -= e.relative.x * mouse_sensitivity\n        pitch = clamp(pitch - e.relative.y * mouse_sensitivity, -89.0, 89.0)\n        rotation_degrees.y = yaw\n        head.rotation_degrees.x = pitch\n\nfunc _physics_process(delta) -> void:\n    if not is_on_floor():\n        velocity.y -= 22.0 * delta\n    if Input.is_key_pressed(KEY_SPACE) and is_on_floor():\n        velocity.y = jump_velocity\n    var input=Vector2(float(Input.is_key_pressed(KEY_D))-float(Input.is_key_pressed(KEY_A)), float(Input.is_key_pressed(KEY_W))-float(Input.is_key_pressed(KEY_S)))\n    var dir=(transform.basis * Vector3(input.x,0.0,-input.y)).normalized() if input.length_squared()>0 else Vector3.ZERO\n    var speed=sprint_speed if Input.is_key_pressed(KEY_SHIFT) else walk_speed\n    velocity.x=move_toward(velocity.x,dir.x*speed,35.0*delta)\n    velocity.z=move_toward(velocity.z,dir.z*speed,35.0*delta)\n    move_and_slide()\n'''
    (out/'scripts/Player.gd').write_text(player, encoding='utf-8')

    return None


def make_world(out: Path, center, chunk_size=512):
    # Start near the center of the imported world. The streamer follows the
    # actual Camera3D, so the full map remains accessible instead of being stuck
    # in the initial 3x3 neighborhood.
    c = center
    spawn = (float(c['x']), 12.0, float(c['z']))
    text='''[gd_scene load_steps=10 format=3]\n\n[ext_resource type="Script" path="res://scripts/WorldStreamer.gd" id="1"]\n[ext_resource type="Script" path="res://scripts/Player.gd" id="2"]\n[sub_resource type="CapsuleShape3D" id="Capsule"]\nradius = 0.35\nheight = 1.8\n[sub_resource type="PlaneMesh" id="WaterMesh"]\nsize = Vector2(12000,12000)\n[sub_resource type="StandardMaterial3D" id="WaterMat"]\nalbedo_color = Color(0.055,0.27,0.38,1)\nroughness = 0.72\ntransparency = 1\nmetallic_specular = 0.15\n[sub_resource type="ProceduralSkyMaterial" id="SkyMaterial"]\nsky_top_color = Color(0.10,0.19,0.34,1)\nsky_horizon_color = Color(0.73,0.79,0.84,1)\nground_bottom_color = Color(0.03,0.04,0.05,1)\nground_horizon_color = Color(0.46,0.50,0.48,1)\n[sub_resource type="Sky" id="Sky"]\nsky_material = SubResource("SkyMaterial")\n[sub_resource type="Environment" id="Environment"]\nbackground_mode = 2\nsky = SubResource("Sky")\nambient_light_source = 3\nambient_light_color = Color(0.60,0.65,0.72,1)\nambient_light_energy = 0.65\ntonemap_mode = 2\n[node name="ViceCity" type="Node3D"]\nscript = ExtResource("1")\nchunk_size = %0.1f\n[node name="WorldEnvironment" type="WorldEnvironment" parent="."]\nenvironment = SubResource("Environment")\n[node name="Water" type="MeshInstance3D" parent="."]\nposition = Vector3(0,-1.0,0)\nmesh = SubResource("WaterMesh")\nmaterial_override = SubResource("WaterMat")\n[node name="Sun" type="DirectionalLight3D" parent="."]\nrotation_degrees = Vector3(-52,-32,0)\nlight_color = Color(1,0.91,0.78,1)\nlight_energy = 1.0\nshadow_enabled = true\n[node name="Player" type="CharacterBody3D" parent="."]\nposition = Vector3(%0.3f,%0.3f,%0.3f)\nscript = ExtResource("2")\n[node name="CollisionShape3D" type="CollisionShape3D" parent="Player"]\nshape = SubResource("Capsule")\n[node name="Head" type="Node3D" parent="Player"]\nposition = Vector3(0,0.72,0)\n[node name="Camera3D" type="Camera3D" parent="Player/Head"]\nposition = Vector3(0,0.18,0)\ncurrent = true\nfov = 75.0\nnear = 0.05\nfar = 4000.0\n'''
    (out/'world/ViceCity.tscn').write_text(text % (float(chunk_size), spawn[0], spawn[1], spawn[2]), encoding='utf-8')
